use std::{fs,path::Path,collections::BTreeMap};use serde_json::{Value,json};use sha2::{Digest,Sha256};
const R:&str="/tmp/zopro-pairing-x-chain-sdk";
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn save(p:impl AsRef<Path>,v:&Value){fs::write(p,serde_json::to_vec_pretty(v).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn main(){let r=Path::new(R);let src=r.join("candidate");let base=read("/tmp/zopro-grouping-module/production-source-manifest.json");let mut pins=BTreeMap::new();let mut changed=Vec::new();for(p,h)in base["source_files_sha256"].as_object().unwrap(){assert_eq!(hash(Path::new("/home/ubuntu/src/zk-tools/zopro").join(p)),h.as_str().unwrap());let path=src.join(p);let actual=hash(&path);if actual!=h.as_str().unwrap(){changed.push(p.clone());}pins.insert(path.display().to_string(),actual);}assert_eq!(changed,vec!["crates/zopro-bn254/src/pairing.rs"]);
 for rel in ["crates/zopro-bn254/src/pairing.rs","crates/zopro-bn254/src/pairing/x_chain.rs"]{assert_eq!(hash(src.join(rel)),hash(Path::new("/tmp/zopro-pairing-x-chain/candidate").join(rel)));}
 for rel in ["candidate/crates/zopro-bn254/src/pairing/x_chain.rs","candidate/crates/zopro-bench/examples/cpu-sdk.rs","candidate/crates/zopro-bench/examples/support/perf.rs","setup.rs","design.md","adapt.rs","pipeline.rs","closeout.rs"]{let p=r.join(rel);pins.insert(p.display().to_string(),hash(p));}save(r.join("source-pins.json"),&json!(pins));save(r.join("implementation-audit.json"),&json!({"status":"pass","accepted_manifest_sha256":hash("/tmp/zopro-grouping-module/production-source-manifest.json"),"base_files":170,"unchanged_originals":169,"changed":changed,"new_modules":["pairing/x_chain.rs"],"exact_component_candidate":true,"new_scratch_Vecs":0,"point_copies_or_tables":0,"typed_workspace_source_unchanged":true,"production_sources_unchanged":true,"adopted":false}));
 let old="/tmp/zopro-g1-quarter-current";let text=serde_json::to_string(&read(format!("{old}/native-plan.json"))).unwrap().replace(old,R).replace("zopro_g1_quarter_current","zopro_pairing_x_chain").replace("ZOPRO_CPU_G1_QUARTER_CURRENT","ZOPRO_CPU_PAIRING_X_CHAIN");let mut plan:Value=serde_json::from_str(&text).unwrap();
 let mut extra=Vec::new();for s in plan["steps"].as_array_mut().unwrap(){if s["name"]=="field"{s["required_tests"]=json!(["pairing::x_chain::tests::symbolic_chain_has_exact_exponent_and_operation_counts","pairing::x_chain::tests::fixed_chain_and_complete_final_match_general_reference"]);}if s["name"]=="on-core"{s["required_tests"]=json!([]);}if [json!("portable-consumers"),json!("no-ifma-consumers")].contains(&s["name"]){let mut test=s.clone();test["name"]=json!(format!("{}-field",s["name"].as_str().unwrap()));test["argv"]=json!(["cargo","test","--manifest-path",src.join("Cargo.toml"),"--offline","--locked","--release","-p","zopro-bn254","--lib","--","--test-threads=1"]);test["unfiltered"]=json!(true);test["required_tests"]=json!(["pairing::x_chain::tests::symbolic_chain_has_exact_exponent_and_operation_counts","pairing::x_chain::tests::fixed_chain_and_complete_final_match_general_reference"]);extra.push(test);}}
 plan["steps"].as_array_mut().unwrap().extend(extra);save(r.join("native-plan.json"),&plan);println!("Pinned{}inputs; fixed schedule byte-exact to component",pins.len());}
